        if identify(out, 64) != 64:
            raise EmbeddedTransportError("invalid embedded build identity")
        return {"source_sha256": bytes(_ffi.buffer(out, 64)).decode("ascii")}

    @property
    def closed(self) -> bool:
        return self._handle == _ffi.NULL

    def execute_json(
        self,
        operation: str,
        payload: dict[str, Any] | None,
        *,
        command_id: str | None,
        deadline_unix_ms: int,
    ) -> dict[str, Any]:
        """Allow concurrent calls while retaining the native handle until each returns."""
        with self._lifecycle:
            if self._closing or self._handle == _ffi.NULL:
                raise EmbeddedTransportError("embedded runtime is closed")
            self._active_calls += 1
        try:
            return self._execute_json(
                operation, payload, command_id=command_id,
                deadline_unix_ms=deadline_unix_ms,
            )
        finally:
            with self._lifecycle:
                self._active_calls -= 1
                self._lifecycle.notify_all()

    def _execute_json(
        self,
        operation: str,
        payload: dict[str, Any] | None,
        *,
        command_id: str | None,
        deadline_unix_ms: int,
    ) -> dict[str, Any]:
        """One storage.v2 operation; returns the daemon response envelope."""
        if self._handle == _ffi.NULL:
            raise EmbeddedTransportError("embedded runtime is closed")
        fields = self._execute_fields
        typed = (fields is not None and type(operation) is str
                 and (command_id is None or type(command_id) is str)
                 and type(deadline_unix_ms) is int and 0 <= deadline_unix_ms < 2**64)
        if typed:
            operation_bytes = operation.encode("utf-8")
            payload_bytes = _dumps(payload if payload is not None else {})
            command_bytes = command_id.encode("utf-8") if command_id is not None else None
        else:
            request = _dumps({"operation": operation, "payload": payload if payload is not None else {},
                              "command_id": command_id, "deadline_unix_ms": deadline_unix_ms})
        out, capacity = _response_buffer()
        for _attempt in range(8):
            if typed:
                written = fields(self._handle, operation_bytes, len(operation_bytes),
                    payload_bytes, len(payload_bytes), command_bytes if command_bytes is not None else _ffi.NULL,
                    len(command_bytes) if command_bytes is not None else 0, deadline_unix_ms, out, capacity)
